      StmtContainsText(S, "list_for_each_entry_safe", SM, LangOpts) ||
      StmtContainsText(S, "list_for_each_entry", SM, LangOpts);
  const bool HasTxList =
      StmtContainsText(S, "tx_ctrl_list", SM, LangOpts) ||
      StmtContainsText(S, "tx_data_list", SM, LangOpts);

  return HasList && HasTxList;
}

static bool IsAcquireStatement(const Stmt *S, const SourceManager &SM,
                               const LangOptions &LangOpts) {
  if (!StmtContainsText(S, "tx_lock", SM, LangOpts))
    return false;

  return StmtContainsText(S, "spin_lock", SM, LangOpts) ||
         StmtContainsText(S, "raw_spin_lock", SM, LangOpts);
}

static bool IsReleaseStatement(const Stmt *S, const SourceManager &SM,
                               const LangOptions &LangOpts) {
  if (!StmtContainsText(S, "tx_lock", SM, LangOpts))
    return false;

  return StmtContainsText(S, "spin_unlock", SM, LangOpts) ||
         StmtContainsText(S, "raw_spin_unlock", SM, LangOpts);
}

static const Stmt *findTargetListLoop(const Stmt *S, ASTContext &ACtx,
                                      const SourceManager &SM,
                                      const LangOptions &LangOpts) {
  DynTypedNode Node = DynTypedNode::create(*S);

  for (unsigned Depth = 0; Depth != 64; ++Depth) {
    auto Parents = ACtx.getParents(Node);
    if (Parents.empty())
      return nullptr;

    const Stmt *Parent = Parents[0].get<Stmt>();
    if (!Parent)
      return nullptr;

    if ((isa<ForStmt>(Parent) || isa<WhileStmt>(Parent) ||
         isa<DoStmt>(Parent)) &&
        ContainsListAndTxTarget(Parent, SM, LangOpts))
      return Parent;

    Node = Parents[0];
  }

  return nullptr;
}

static bool isLoopProtectedByTxLock(const Stmt *Loop, ASTContext &ACtx,
                                    const SourceManager &SM,
                                    const LangOptions &LangOpts) {
  DynTypedNode Node = DynTypedNode::create(*Loop);
  const CompoundStmt *EnclosingBlock = nullptr;

  for (unsigned Depth = 0; Depth != 64; ++Depth) {
    auto Parents = ACtx.getParents(Node);
    if (Parents.empty())
      return false;

    if (const auto *Block = Parents[0].get<CompoundStmt>()) {
      EnclosingBlock = Block;
      break;
    }

    if (!Parents[0].get<Stmt>())
      return false;

    Node = Parents[0];
  }

  if (!EnclosingBlock)
    return false;

  bool LoopFound = false;
  bool LockAcquiredBeforeLoop = false;
  bool LockReleasedAfterLoop = false;

  for (const Stmt *Child : EnclosingBlock->body()) {
    if (!Child)
      continue;

    if (Child == Loop) {
      LoopFound = true;
      continue;
    }

    if (!LoopFound) {
      if (IsAcquireStatement(Child, SM, LangOpts))
        LockAcquiredBeforeLoop = true;
      continue;
    }

    if (IsReleaseStatement(Child, SM, LangOpts)) {
      LockReleasedAfterLoop = true;
      break;
    }
  }

  return LoopFound && LockAcquiredBeforeLoop && LockReleasedAfterLoop;
}

class SAGenTestChecker : public Checker<check::ASTCodeBody> {
public:
  void checkASTCodeBody(const Decl *D, AnalysisManager &Mgr,
                        BugReporter &BR) const;
};

class FreeCallVisitor : public RecursiveASTVisitor<FreeCallVisitor> {
public:
  FreeCallVisitor(const FunctionDecl *FD, ASTContext &ACtx, BugReporter &BR,
                  const CheckerBase *Checker)
      : FD(FD), ACtx(ACtx), BR(BR), Checker(Checker),
        SM(ACtx.getSourceManager()), LangOpts(ACtx.getLangOpts()) {}

  bool VisitCallExpr(const CallExpr *Call) {
    const FunctionDecl *Callee = Call->getDirectCallee();
    if (!Callee)
      return true;

    const IdentifierInfo *ID = Callee->getIdentifier();
    if (!ID || (!ID->isStr("kfree") && !ID->isStr("kvfree")))
      return true;

    const Stmt *Loop =
        findTargetListLoop(Call, ACtx, SM, LangOpts);
    if (!Loop || isLoopProtectedByTxLock(Loop, ACtx, SM, LangOpts))
      return true;

    PathDiagnosticLocation Loc =
        PathDiagnosticLocation::createBegin(Call, SM);
    SourceRange Ranges[] = {Call->getSourceRange()};

    BR.EmitBasicReport(
        FD, Checker, "Unsafe list free without tx_lock", "Concurrency",
        "Freeing tx_* list entries without holding tx_lock (possible UAF)",
        Loc, Ranges);

    return true;
  }

private:
  const FunctionDecl *FD;
  ASTContext &ACtx;
  BugReporter &BR;
  const CheckerBase *Checker;
  const SourceManager &SM;
  const LangOptions &LangOpts;
};

void SAGenTestChecker::checkASTCodeBody(const Decl *D, AnalysisManager &Mgr,
                                        BugReporter &BR) const {
  const auto *FD = dyn_cast<FunctionDecl>(D);
  if (!FD || !FD->getBody())
    return;

  FreeCallVisitor Visitor(FD, Mgr.getASTContext(), BR, this);
  Visitor.TraverseStmt(const_cast<Stmt *>(FD->getBody()));
}

} // namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
      "Detects freeing tx_* list entries without holding tx_lock during list traversal (possible UAF)",
      "");
}

