// ---------- Helper implementations ----------

bool SAGenTestChecker::isDirectReleaseCall(const CallEvent &Call,
                                           CheckerContext &C) {
  const Expr *OE = Call.getOriginExpr();
  if (!OE)
    return false;

  for (const char *N : DirectReleaseFns) {
    if (ExprHasName(OE, N, C))
      return true;
  }
  return false;
}

const OwnerReleaseSpec *
SAGenTestChecker::matchOwnerRelease(const CallEvent &Call, CheckerContext &C) {
  const Expr *OE = Call.getOriginExpr();
  if (!OE)
    return nullptr;

  for (const auto &Spec : OwnerReleases) {
    if (ExprHasName(OE, Spec.FuncName, C))
      return &Spec;
  }
  return nullptr;
}

const FieldDecl *SAGenTestChecker::findFieldDeclByName(
    QualType Ty, StringRef FieldName) const {
  if (Ty->isPointerType())
    Ty = Ty->getPointeeType();

  const RecordType *RT = Ty->getAs<RecordType>();
  if (!RT)
    return nullptr;

  const RecordDecl *RD = RT->getDecl();
  if (!RD)
    return nullptr;

  for (const FieldDecl *FD : RD->fields()) {
    if (FD->getName() == FieldName)
      return FD;
  }
  return nullptr;
}

// Get a base region representing the object instance referred to by BaseExpr.
// For pointer base, use the region or symbol for the pointee. For non-pointer
// base (struct lvalue), use its region directly.
const MemRegion *SAGenTestChecker::getObjectBaseRegionFromExpr(
    const Expr *BaseExpr, CheckerContext &C) const {
  if (!BaseExpr)
    return nullptr;

  ProgramStateRef State = C.getState();
  const LocationContext *LCtx = C.getLocationContext();
  SVal V = State->getSVal(BaseExpr, LCtx);
  auto &MRMgr = C.getSValBuilder().getRegionManager();

  if (const MemRegion *R = V.getAsRegion())
    return R->getBaseRegion();

  if (BaseExpr->getType()->isPointerType()) {
    if (SymbolRef Sym = V.getAsSymbol()) {
      const MemRegion *SR = MRMgr.getSymbolicRegion(Sym);
      return SR ? SR->getBaseRegion() : nullptr;
    }
  } else if (const MemRegion *R = getMemRegionFromExpr(BaseExpr, C)) {
    return R->getBaseRegion();
  }

  return nullptr;
}

const MemRegion *SAGenTestChecker::buildFieldRegion(
    const MemRegion *BaseObj, const FieldDecl *FD, CheckerContext &C) const {
  if (!BaseObj || !FD)
    return nullptr;

  auto &MRMgr = C.getSValBuilder().getRegionManager();
  const auto *SR = dyn_cast<SubRegion>(BaseObj);
  if (!SR)
    return nullptr;

  return MRMgr.getFieldRegion(FD, SR);
}

const MemRegion *SAGenTestChecker::buildFieldRegionFromMemberExpr(
    const MemberExpr *ME, CheckerContext &C) const {
  if (!ME)
    return nullptr;

  const FieldDecl *FD = dyn_cast<FieldDecl>(ME->getMemberDecl());
  if (!FD)
    return nullptr;

  const MemRegion *ObjBase =
      getObjectBaseRegionFromExpr(ME->getBase(), C);
  if (!ObjBase)
    return nullptr;

  return buildFieldRegion(ObjBase, FD, C);
}

void SAGenTestChecker::markReleased(const MemRegion *FieldReg,
                                    const Stmt *Site,
                                    CheckerContext &C) const {
  if (!FieldReg)
    return;

  ProgramStateRef State = C.getState();
  State = State->add<ReleasedFieldSet>(FieldReg);
  State = State->set<ReleaseSiteMap>(FieldReg, Site);
  State = State->set<ReleaseFunctionMap>(
      FieldReg, C.getLocationContext()->getDecl());
  C.addTransition(State);
}

