void SAGenTestChecker::checkPostCall(const CallEvent &Call,
                                     CheckerContext &C) const {
  // Direct release: fput(device->field), filp_close(...), blkdev_put(...).
  if (isDirectReleaseCall(Call, C)) {
    if (Call.getNumArgs() >= 1) {
      const Expr *ArgE = Call.getArgExpr(0);
      if (const auto *ME =
              dyn_cast_or_null<MemberExpr>(
                  ArgE ? ArgE->IgnoreParenCasts() : nullptr)) {
        const MemRegion *FieldReg = buildFieldRegionFromMemberExpr(ME, C);
        if (FieldReg)
          markReleased(FieldReg, Call.getOriginExpr(), C);
      }
    }
    return;
  }

  // Owner release: e.g., btrfs_close_bdev(device) releases device->bdev_file.
  if (const OwnerReleaseSpec *Spec = matchOwnerRelease(Call, C)) {
    if (Spec->ObjParamIndex >= Call.getNumArgs())
      return;

    const Expr *ObjArgE = Call.getArgExpr(Spec->ObjParamIndex);
    const MemRegion *ObjBase = getObjectBaseRegionFromExpr(ObjArgE, C);

    if (!ObjBase) {
      SVal ArgV = Call.getArgSVal(Spec->ObjParamIndex);
      auto &MRMgr = C.getSValBuilder().getRegionManager();
      if (SymbolRef Sym = ArgV.getAsSymbol())
        ObjBase = MRMgr.getSymbolicRegion(Sym);
    }

    if (!ObjBase)
      return;

    const FieldDecl *FD =
        findFieldDeclByName(ObjArgE->getType(), Spec->FieldName);
    const MemRegion *FieldReg = buildFieldRegion(ObjBase, FD, C);
    if (FieldReg)
      markReleased(FieldReg, Call.getOriginExpr(), C);
  }
}

void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  ProgramStateRef State = C.getState();

  for (unsigned i = 0, e = Call.getNumArgs(); i != e; ++i) {
    const Expr *ArgE = Call.getArgExpr(i);
    if (!ArgE)
      continue;

    const auto *ME =
        dyn_cast<MemberExpr>(ArgE->IgnoreParenCasts());
    if (!ME)
      continue;

    const MemRegion *FieldReg = buildFieldRegionFromMemberExpr(ME, C);
    if (FieldReg && State->contains<ReleasedFieldSet>(FieldReg)) {
      reportUseInCall(FieldReg, Call, C);
      return;
    }
  }
}

void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S,
                                 CheckerContext &C) const {
  const auto *BO = dyn_cast_or_null<BinaryOperator>(S);
  if (!BO || !BO->isAssignmentOp())
    return;

  const Expr *LHS = BO->getLHS()->IgnoreParenCasts();
  const auto *ME = dyn_cast<MemberExpr>(LHS);
  if (!ME)
    return;

  const MemRegion *FieldReg = buildFieldRegionFromMemberExpr(ME, C);
  if (!FieldReg)
    return;

  ProgramStateRef State = C.getState();
  if (!State->contains<ReleasedFieldSet>(FieldReg) || Val.isUnknownOrUndef())
    return;

  State = State->remove<ReleasedFieldSet>(FieldReg);
  State = State->remove<ReleaseSiteMap>(FieldReg);
  State = State->remove<ReleaseFunctionMap>(FieldReg);
  C.addTransition(State);
}

void SAGenTestChecker::checkBranchCondition(const Stmt *Condition,
                                            CheckerContext &C) const {
  ProgramStateRef State = C.getState();

  const MemberExpr *ME = findSpecificTypeInChildren<MemberExpr>(Condition);
  if (!ME) {
    C.addTransition(State);
    return;
  }

  const MemRegion *FieldReg = buildFieldRegionFromMemberExpr(ME, C);
  if (FieldReg && State->contains<ReleasedFieldSet>(FieldReg)) {
    reportUseInCondition(FieldReg, Condition, C);
    return;
  }

  C.addTransition(State);
}

void SAGenTestChecker::checkEndFunction(const ReturnStmt *RS,
                                        CheckerContext &C) const {
  ProgramStateRef State = C.getState();
  const Decl *CurrentDecl = C.getLocationContext()->getDecl();

  // Only report at the exit of the function that recorded the release.
  // Analyzer state can persist through inlined calls, whose exits are not
  // evidence that this function returned with its field still dangling.
  for (const MemRegion *FieldReg : State->get<ReleasedFieldSet>()) {
    const Decl *const *ReleaseDeclP =
        State->get<ReleaseFunctionMap>(FieldReg);
    if (ReleaseDeclP && *ReleaseDeclP == CurrentDecl)
      reportNotClearedAtReturn(FieldReg, C);
  }
}

