        return true;
    }
  }

  // Heuristic text search for common names
  if (ExprHasName(LenE, "nbytes", C) || ExprHasName(LenE, "count", C))
    return true;

  return false;
}

bool SAGenTestChecker::lengthIsBoundedByArray(const CallEvent &Call,
                                              unsigned LenArgIndex,
                                              const llvm::APInt &ArrSize,
                                              CheckerContext &C) const {
  if (LenArgIndex >= Call.getNumArgs())
    return false;

  SVal LenVal = Call.getArgSVal(LenArgIndex);
  SymbolRef LenSym = LenVal.getAsSymbol();
  if (!LenSym)
    return false;

  const llvm::APSInt *MaxVal = inferSymbolMaxVal(LenSym, C);
  if (!MaxVal)
    return false;

  // Compare as unsigned values at a common width. A signed negative maximum
  // becomes a large unsigned value here, so it will not accidentally suppress
  // a warning.
  unsigned Width = std::max(MaxVal->getBitWidth(), ArrSize.getBitWidth());
  llvm::APInt MaxBits = MaxVal->getValue().zextOrTrunc(Width);
  llvm::APInt SizeBits = ArrSize.zextOrTrunc(Width);
  return MaxBits.ule(SizeBits);
}

