  // Direct parameter reference named "nbytes" or "count".
  if (const auto *DRE =
          dyn_cast<DeclRefExpr>(LenE->IgnoreParenImpCasts())) {
    if (const auto *PVD = dyn_cast<ParmVarDecl>(DRE->getDecl())) {
      StringRef N = PVD->getName();
      if (N.equals("nbytes") || N.equals("count"))
        return true;
