bool SAGenTestChecker::isLengthProvenWithinBounds(
    const CallEvent &Call, const llvm::APInt &ArrSize,
    CheckerContext &C) const {
  if (Call.getNumArgs() < 3)
    return false;

  SVal LenVal = Call.getArgSVal(2);
  SymbolRef LenSym = LenVal.getAsSymbol();
  if (!LenSym)
    return false;

  const llvm::APSInt *MaxVal =
      inferSymbolMaxVal(LenSym, C);
  if (!MaxVal)
    return false;

  // A negative signed maximum does not establish a safe unsigned copy length.
  if (MaxVal->isSigned() && MaxVal->isNegative())
    return false;

  const llvm::APInt &Max = MaxVal->getValue();
  unsigned Width = std::max(Max.getBitWidth(), ArrSize.getBitWidth());

  llvm::APInt MaxUnsigned = Max.zextOrTrunc(Width);
  llvm::APInt ArraySizeUnsigned = ArrSize.zextOrTrunc(Width);
  return MaxUnsigned.ule(ArraySizeUnsigned);
}

