// Program state map: pointer MemRegion -> destination fixed-size array VarDecl
REGISTER_MAP_WITH_PROGRAMSTATE(BufAliasMap, const MemRegion *, const VarDecl *)

namespace {

class SAGenTestChecker : public Checker<check::PreCall, check::Bind> {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "copy_from_user into fixed-size buffer",
                       "Memory Error")) {}

  void checkPreCall(const CallEvent &Call, CheckerContext &C) const;
  void checkBind(SVal Loc, SVal Val, const Stmt *S,
                 CheckerContext &C) const;

private:
  bool isCopyFromUser(const CallEvent &Call, CheckerContext &C) const;
  bool getArrayFromDestExpr(const Expr *Dest, const VarDecl *&ArrVD,
                            llvm::APInt &ArrSize,
                            CheckerContext &C) const;
  bool lenExprLooksUnboundedUserCount(const Expr *LenE, const VarDecl *ArrVD,
                                      CheckerContext &C) const;
  bool isLengthProvenWithinBuffer(SVal LengthVal,
                                 const llvm::APInt &ArrSize,
                                 CheckerContext &C) const;
  void reportUnbounded(const CallEvent &Call, const Expr *DestE,
                       CheckerContext &C, StringRef Msg) const;
};

bool SAGenTestChecker::isCopyFromUser(const CallEvent &Call,
                                      CheckerContext &C) const {
  const Expr *Origin = Call.getOriginExpr();
  if (!Origin)
    return false;

  if (ExprHasName(Origin, "copy_from_user", C))
    return true;
  if (ExprHasName(Origin, "__copy_from_user", C))
    return true;

  return false;
}

bool SAGenTestChecker::getArrayFromDestExpr(const Expr *Dest,
                                            const VarDecl *&ArrVD,
                                            llvm::APInt &ArrSize,
                                            CheckerContext &C) const {
  ArrVD = nullptr;
  if (!Dest)
    return false;

  // Direct array use: copy_from_user(mybuf, ...)
  if (const auto *DRE =
          dyn_cast<DeclRefExpr>(Dest->IgnoreParenImpCasts())) {
    if (const auto *VD = dyn_cast<VarDecl>(DRE->getDecl())) {
      if (const auto *CAT =
              dyn_cast<ConstantArrayType>(VD->getType().getTypePtr())) {
        ArrVD = VD;
        ArrSize = CAT->getSize();
        return true;
      }
    }
  }

  // Alias use: pbuf = mybuf; copy_from_user(pbuf, ...)
  const MemRegion *MR = getMemRegionFromExpr(Dest, C);
  if (!MR)
    return false;

  MR = MR->getBaseRegion();
  if (!MR)
    return false;

  ProgramStateRef State = C.getState();
  const VarDecl *const *VDPtr = State->get<BufAliasMap>(MR);
  if (!VDPtr || !*VDPtr)
    return false;

  const VarDecl *VD = *VDPtr;
  if (const auto *CAT =
          dyn_cast<ConstantArrayType>(VD->getType().getTypePtr())) {
    ArrVD = VD;
    ArrSize = CAT->getSize();
    return true;
  }

  return false;
}

bool SAGenTestChecker::lenExprLooksUnboundedUserCount(
    const Expr *LenE, const VarDecl *ArrVD, CheckerContext &C) const {
  if (!LenE)
    return false;

  // Preserve the existing simple clamp heuristics.
  if (ExprHasName(LenE, "min", C))
    return false;

  if (ArrVD && ExprHasName(LenE, "sizeof", C) &&
      ExprHasName(LenE, ArrVD->getName(), C))
    return false;

  if (const auto *DRE =
          dyn_cast<DeclRefExpr>(LenE->IgnoreParenImpCasts())) {
    if (const auto *PVD = dyn_cast<ParmVarDecl>(DRE->getDecl())) {
      StringRef Name = PVD->getName();
      if (Name.equals("nbytes") || Name.equals("count"))
        return true;
    }
  }

  return ExprHasName(LenE, "nbytes", C) || ExprHasName(LenE, "count", C);
}

bool SAGenTestChecker::isLengthProvenWithinBuffer(
    SVal LengthVal, const llvm::APInt &ArrSize,
    CheckerContext &C) const {
  // Concrete lengths are handled separately by EvaluateExprToInt().
  SymbolRef Sym = LengthVal.getAsSymbol();
  if (!Sym)
    return false;

  const llvm::APSInt *MaxVal =
      C.getState()->getConstraintManager().getSymMaxVal(C.getState(), Sym);
  if (!MaxVal)
    return false;

  // A negative signed maximum cannot establish a safe size_t copy length.
  if (MaxVal->isSigned() && MaxVal->isNegative())
    return false;

  llvm::APInt MaxBits =
      MaxVal->getValue().zextOrTrunc(ArrSize.getBitWidth());
  return MaxBits.ule(ArrSize);
}

void SAGenTestChecker::reportUnbounded(const CallEvent &Call,
                                       const Expr *DestE,
                                       CheckerContext &C,
                                       StringRef Msg) const {
  ExplodedNode *EN = C.generateNonFatalErrorNode();
  if (!EN)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(*BT, Msg, EN);
  R->addRange(Call.getSourceRange());
  if (DestE)
    R->addRange(DestE->getSourceRange());
  C.emitReport(std::move(R));
}

void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  if (!isCopyFromUser(Call, C) || Call.getNumArgs() < 3)
    return;

  const Expr *DestE = Call.getArgExpr(0);
  const Expr *LenE = Call.getArgExpr(2);
  if (!DestE || !LenE)
    return;

  const VarDecl *ArrVD = nullptr;
  llvm::APInt ArrSize;
  if (!getArrayFromDestExpr(DestE, ArrVD, ArrSize, C))
    return;

  llvm::APSInt EvalRes;
  if (EvaluateExprToInt(EvalRes, LenE, C)) {
    if (EvalRes.isSigned() && EvalRes.isNegative())
      return;

    llvm::APInt LenBits =
        EvalRes.getValue().zextOrTrunc(ArrSize.getBitWidth());
    if (LenBits.ugt(ArrSize)) {
      reportUnbounded(Call, DestE, C,
                      "copy_from_user length exceeds destination buffer");
    }
    return;
  }

  // Respect path constraints established by guards or prior assignments.
  // For example, on the false branch of
  // `if (nbytes > sizeof(mybuf) - 1)`, the analyzer knows nbytes is bounded.
  if (isLengthProvenWithinBuffer(Call.getArgSVal(2), ArrSize, C))
    return;

  if (lenExprLooksUnboundedUserCount(LenE, ArrVD, C)) {
    reportUnbounded(
        Call, DestE, C,
        "copy_from_user into fixed-size buffer uses unbounded user length");
  }
}

void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S,
                                CheckerContext &C) const {
  ProgramStateRef State = C.getState();

  const MemRegion *LHSReg = Loc.getAsRegion();
  if (!LHSReg)
    return;

  LHSReg = LHSReg->getBaseRegion();
  if (!LHSReg)
    return;

  const MemRegion *RHSReg = Val.getAsRegion();
  if (RHSReg)
    RHSReg = RHSReg->getBaseRegion();

  const VarDecl *ArrayVD = nullptr;
  if (RHSReg) {
    if (const auto *VR = dyn_cast<VarRegion>(RHSReg)) {
      const VarDecl *VD = VR->getDecl();
      if (VD && dyn_cast<ConstantArrayType>(VD->getType().getTypePtr()))
        ArrayVD = VD;
    }
  }

  // Update or clear the alias entry so reassignment cannot retain stale
  // information about a previous array target.
  const VarDecl *const *Existing = State->get<BufAliasMap>(LHSReg);
  if (ArrayVD) {
    if (!Existing || *Existing != ArrayVD)
      C.addTransition(State->set<BufAliasMap>(LHSReg, ArrayVD));
  } else if (Existing) {
    C.addTransition(State->remove<BufAliasMap>(LHSReg));
  }
}

} // namespace

