REGISTER_MAP_WITH_PROGRAMSTATE(BufAliasMap, const MemRegion *, const VarDecl *)

namespace {

class SAGenTestChecker : public Checker<check::PreCall, check::Bind> {
  mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "copy_from_user into fixed-size buffer",
                       "Memory Error")) {}

  void checkPreCall(const CallEvent &Call, CheckerContext &C) const;
  void checkBind(SVal Loc, SVal Val, const Stmt *S, CheckerContext &C) const;

private:
  bool isCopyFromUser(const CallEvent &Call, CheckerContext &C) const;
  bool getArrayFromDestExpr(const Expr *Dest, const VarDecl *&ArrVD,
                            llvm::APInt &ArrSize,
                            CheckerContext &C) const;
  bool lenExprLooksUnboundedUserCount(const Expr *LenE, const VarDecl *ArrVD,
                                      CheckerContext &C) const;
  bool isLengthProvablyWithinArray(const Expr *LenE,
                                   const llvm::APInt &ArrSize,
                                   CheckerContext &C) const;
  void reportUnbounded(const CallEvent &Call, const Expr *DestE,
                       CheckerContext &C, StringRef Msg) const;
};

bool SAGenTestChecker::isCopyFromUser(const CallEvent &Call,
                                      CheckerContext &C) const {
  const Expr *Origin = Call.getOriginExpr();
  if (!Origin)
    return false;

  if (ExprHasName(Origin, "copy_from_user", C))
    return true;
  if (ExprHasName(Origin, "__copy_from_user", C))
    return true;
  return false;
}

bool SAGenTestChecker::getArrayFromDestExpr(const Expr *Dest,
                                            const VarDecl *&ArrVD,
                                            llvm::APInt &ArrSize,
                                            CheckerContext &C) const {
  ArrVD = nullptr;

  // Try direct array use: e.g., copy_from_user(mybuf, ...)
  if (const auto *DRE =
          dyn_cast<DeclRefExpr>(Dest->IgnoreParenImpCasts())) {
    if (const auto *VD = dyn_cast<VarDecl>(DRE->getDecl())) {
      if (const auto *CAT =
              dyn_cast<ConstantArrayType>(VD->getType().getTypePtr())) {
        ArrVD = VD;
        ArrSize = CAT->getSize();
        return true;
      }
    }
  }

  // Try alias via program state map: e.g., pbuf = mybuf; copy_from_user(pbuf, ...)
  const MemRegion *MR = getMemRegionFromExpr(Dest, C);
  if (!MR)
    return false;
  MR = MR->getBaseRegion();
  if (!MR)
    return false;

  ProgramStateRef State = C.getState();
  const VarDecl *const *VDPtr = State->get<BufAliasMap>(MR);
  if (!VDPtr)
    return false;

  const VarDecl *VD = *VDPtr;
  if (!VD)
    return false;

  if (const auto *CAT =
          dyn_cast<ConstantArrayType>(VD->getType().getTypePtr())) {
    ArrVD = VD;
    ArrSize = CAT->getSize();
    return true;
  }

  return false;
}

bool SAGenTestChecker::lenExprLooksUnboundedUserCount(
    const Expr *LenE, const VarDecl *ArrVD, CheckerContext &C) const {
  if (!LenE)
    return false;

  // Preserve the existing source-level recognition of explicit clamps.
  if (ExprHasName(LenE, "min", C))
    return false;

  if (ArrVD) {
    if (ExprHasName(LenE, "sizeof", C) &&
        ExprHasName(LenE, ArrVD->getName(), C))
      return false;
  }

  if (const auto *DRE =
          dyn_cast<DeclRefExpr>(LenE->IgnoreParenImpCasts())) {
    if (const auto *PVD = dyn_cast<ParmVarDecl>(DRE->getDecl())) {
      StringRef N = PVD->getName();
      if (N.equals("nbytes") || N.equals("count"))
        return true;
    }
  }

  return ExprHasName(LenE, "nbytes", C) || ExprHasName(LenE, "count", C);
}

bool SAGenTestChecker::isLengthProvablyWithinArray(
    const Expr *LenE, const llvm::APInt &ArrSize, CheckerContext &C) const {
  if (!LenE)
    return false;

  // A concrete value is the most precise bound available.
  llvm::APSInt ConstantLen;
  if (EvaluateExprToInt(ConstantLen, LenE, C)) {
    if (ConstantLen.isSigned() && ConstantLen.isNegative())
      return false;

    llvm::APInt LenValue = ConstantLen.getValue();
    unsigned Width = std::max(LenValue.getBitWidth(), ArrSize.getBitWidth());
    LenValue = LenValue.zextOrTrunc(Width);
    llvm::APInt ArrayValue = ArrSize.zextOrTrunc(Width);
    return LenValue.ule(ArrayValue);
  }

  // Respect path constraints, including bounds established by an earlier
  // conditional clamp such as:
  //   if (nbytes > sizeof(buf) - 1)
  //     nbytes = sizeof(buf) - 1;
  SymbolRef Sym = C.getSVal(LenE).getAsSymbol();
  if (!Sym)
    return false;

  const llvm::APSInt *MaxVal = inferSymbolMaxVal(Sym, C);
  if (!MaxVal)
    return false;

  // A negative signed upper bound does not prove safety after conversion to
  // the unsigned size_t argument expected by copy_from_user().
  if (MaxVal->isSigned() && MaxVal->isNegative())
    return false;

  llvm::APInt MaxValue = MaxVal->getValue();
  unsigned Width = std::max(MaxValue.getBitWidth(), ArrSize.getBitWidth());
  MaxValue = MaxValue.zextOrTrunc(Width);
  llvm::APInt ArrayValue = ArrSize.zextOrTrunc(Width);
  return MaxValue.ule(ArrayValue);
}

void SAGenTestChecker::reportUnbounded(const CallEvent &Call,
                                       const Expr *DestE, CheckerContext &C,
                                       StringRef Msg) const {
  ExplodedNode *EN = C.generateNonFatalErrorNode();
  if (!EN)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(*BT, Msg, EN);
  R->addRange(Call.getSourceRange());
  if (DestE)
    R->addRange(DestE->getSourceRange());
  C.emitReport(std::move(R));
}

void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  if (!isCopyFromUser(Call, C))
    return;

  if (Call.getNumArgs() < 3)
    return;

  const Expr *DestE = Call.getArgExpr(0);
  const Expr *LenE = Call.getArgExpr(2);
  if (!DestE || !LenE)
    return;

  const VarDecl *ArrVD = nullptr;
  llvm::APInt ArrSize;
  if (!getArrayFromDestExpr(DestE, ArrVD, ArrSize, C))
    return;

  // A proven upper bound takes precedence over parameter-name heuristics.
  // This avoids reporting lengths clamped on the current analyzer path.
  if (isLengthProvablyWithinArray(LenE, ArrSize, C))
    return;

  // Preserve detection of concrete oversized lengths.
  llvm::APSInt EvalRes;
  if (EvaluateExprToInt(EvalRes, LenE, C)) {
    if (EvalRes.isSigned() && EvalRes.isNegative())
      return;

    llvm::APInt LenValue = EvalRes.getValue();
    unsigned Width = std::max(LenValue.getBitWidth(), ArrSize.getBitWidth());
    LenValue = LenValue.zextOrTrunc(Width);
    llvm::APInt ArrayValue = ArrSize.zextOrTrunc(Width);

    if (LenValue.ugt(ArrayValue)) {
      reportUnbounded(Call, DestE, C,
                      "copy_from_user length exceeds destination buffer");
    }
    return;
  }

  // If no safe symbolic bound is known, retain the existing user-count
  // heuristic. The unmodified buggy code passes unconstrained nbytes here.
  if (lenExprLooksUnboundedUserCount(LenE, ArrVD, C)) {
    reportUnbounded(Call, DestE, C,
                    "copy_from_user into fixed-size buffer uses unbounded user length");
  }
}

void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S,
                                 CheckerContext &C) const {
  ProgramStateRef State = C.getState();

  const MemRegion *LHSReg = Loc.getAsRegion();
  if (!LHSReg)
    return;
  LHSReg = LHSReg->getBaseRegion();
  if (!LHSReg)
    return;

  const MemRegion *RHSReg = Val.getAsRegion();
  if (!RHSReg)
    return;
  RHSReg = RHSReg->getBaseRegion();
  if (!RHSReg)
    return;

  // Track pointer aliases to fixed-size arrays.
  if (const auto *VR = dyn_cast<VarRegion>(RHSReg)) {
    const VarDecl *VD = VR->getDecl();
    if (!VD)
      return;

    if (dyn_cast<ConstantArrayType>(VD->getType().getTypePtr())) {
      State = State->set<BufAliasMap>(LHSReg, VD);
      C.addTransition(State);
    }
  }
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
      "Detect unbounded copy_from_user into fixed-size local buffers", "");
}

