bool SAGenTestChecker::isFuncNamed(const CallEvent &Call, CheckerContext &C,
                                   StringRef Name) const {
  const IdentifierInfo *ID = Call.getCalleeIdentifier();
  return ID && ID->getName() == Name;
}

bool SAGenTestChecker::extractAddrOfLocalRecordVar(const Expr *E,
                                                   const VarDecl *&VD) const {
  if (!E)
    return false;

  E = E->IgnoreParenCasts();
  const auto *UO = dyn_cast<UnaryOperator>(E);
  if (!UO || UO->getOpcode() != UO_AddrOf)
    return false;

  const Expr *Sub = UO->getSubExpr();
  if (!Sub)
    return false;

  Sub = Sub->IgnoreParenCasts();
  const auto *DRE = dyn_cast<DeclRefExpr>(Sub);
  if (!DRE)
    return false;

  VD = dyn_cast<VarDecl>(DRE->getDecl());
  if (!VD)
    return false;

  QualType T = VD->getType();
  if (T.isNull() || !T->isRecordType())
    return false;

  return VD->hasLocalStorage() && !VD->hasGlobalStorage();
}

bool SAGenTestChecker::isZeroValueExpr(const Expr *E, CheckerContext &C) const {
  if (!E)
    return false;

  llvm::APSInt Val;
  return EvaluateExprToInt(Val, E, C) && Val.isZero();
}

bool SAGenTestChecker::sizeMatchesWholeObject(const Expr *SizeE,
                                              const VarDecl *VD,
                                              CheckerContext &C) const {
  if (!SizeE || !VD)
    return false;

  if (const auto *UETT =
          findSpecificTypeInChildren<UnaryExprOrTypeTraitExpr>(SizeE)) {
    if (UETT->getKind() == UETT_SizeOf) {
      if (UETT->isArgumentType()) {
        QualType ArgTy = UETT->getArgumentType();
        if (!ArgTy.isNull() &&
            C.getASTContext().hasSameType(
                ArgTy.getUnqualifiedType(),
                VD->getType().getUnqualifiedType()))
          return true;
      } else if (const Expr *Arg = UETT->getArgumentExpr()) {
        Arg = Arg->IgnoreParenCasts();
        if (const auto *DRE = dyn_cast<DeclRefExpr>(Arg))
          if (DRE->getDecl() == VD)
            return true;
      }
    }
  }

  llvm::APSInt Val;
  if (!EvaluateExprToInt(Val, SizeE, C) || !Val.isNonNegative())
    return false;

  uint64_t ObjSizeBytes =
      C.getASTContext().getTypeSizeInChars(VD->getType()).getQuantity();
  return Val.getZExtValue() == ObjSizeBytes;
}

bool SAGenTestChecker::typeHasPadding(QualType T, ASTContext &Ctx) const {
  if (T.isNull())
    return false;

  if (const auto *AT = Ctx.getAsArrayType(T))
    return typeHasPadding(AT->getElementType(), Ctx);

  const auto *RT = T->getAs<RecordType>();
  return RT && recordHasPadding(RT->getDecl(), Ctx);
}

bool SAGenTestChecker::recordHasPadding(const RecordDecl *RD,
                                        ASTContext &Ctx) const {
  if (!RD || !RD->isCompleteDefinition())
    return false;

  const ASTRecordLayout &Layout = Ctx.getASTRecordLayout(RD);
  uint64_t RecordSizeBits =
      Ctx.getTypeSize(QualType(RD->getTypeForDecl(), 0));
  uint64_t EndBits = 0;

  for (const FieldDecl *Field : RD->fields()) {
    // A nested record can leak its own padding even when this record has no
    // gaps between its immediate fields.
    if (typeHasPadding(Field->getType(), Ctx))
      return true;

    uint64_t OffsetBits = Layout.getFieldOffset(Field->getFieldIndex());
    uint64_t FieldSizeBits =
        Field->isBitField()
            ? Field->getBitWidthValue(Ctx)
            : Ctx.getTypeSize(Field->getType());

    if (!RD->isUnion() && OffsetBits > EndBits)
      return true;

    EndBits = std::max(EndBits, OffsetBits + FieldSizeBits);
  }

  // This also catches trailing padding. For unions it catches unused bytes
  // after the largest member.
  return EndBits < RecordSizeBits;
}

void SAGenTestChecker::recordWholeObjectZeroing(
    const CallEvent &Call, CheckerContext &C, unsigned DstIdx,
    unsigned SizeIdx) const {
  if (Call.getNumArgs() <= std::max(DstIdx, SizeIdx))
    return;

  const Expr *DstExpr = Call.getArgExpr(DstIdx);
  const Expr *SizeExpr = Call.getArgExpr(SizeIdx);
  if (!DstExpr || !SizeExpr)
    return;

  const VarDecl *VD = nullptr;
  if (!extractAddrOfLocalRecordVar(DstExpr, VD) ||
      !sizeMatchesWholeObject(SizeExpr, VD, C))
    return;

  const MemRegion *MR = getMemRegionFromExpr(DstExpr, C);
  if (!MR)
    return;

  MR = MR->getBaseRegion();
  if (!MR)
    return;

  C.addTransition(C.getState()->add<ZeroedStructSet>(MR));
}

bool SAGenTestChecker::matchSink(const CallEvent &Call, CheckerContext &C,
                                 unsigned &LenIdx,
                                 unsigned &DataIdx) const {
  struct SinkInfo {
    StringRef Name;
    unsigned LenIndex;
    unsigned DataIndex;
  };

  static const SinkInfo Sinks[] = {
      {"nla_put", 2u, 3u},
      {"nla_put_64bit", 2u, 3u},
  };

  for (const auto &Sink : Sinks) {
    if (isFuncNamed(Call, C, Sink.Name)) {
      LenIdx = Sink.LenIndex;
      DataIdx = Sink.DataIndex;
      return true;
    }
  }

  return false;
}

void SAGenTestChecker::reportLeak(const CallEvent &Call,
                                  CheckerContext &C) const {
  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  auto R = std::make_unique<PathSensitiveBugReport>(
      *BT, "stack struct not fully zeroed before user copy (padding leak)", N);
  R->addRange(Call.getSourceRange());
  C.emitReport(std::move(R));
}

void SAGenTestChecker::checkPostCall(const CallEvent &Call,
                                     CheckerContext &C) const {
  if (isFuncNamed(Call, C, "memset") ||
      isFuncNamed(Call, C, "__builtin_memset")) {
    if (Call.getNumArgs() >= 3 &&
        isZeroValueExpr(Call.getArgExpr(1), C))
      recordWholeObjectZeroing(Call, C, /*DstIdx=*/0, /*SizeIdx=*/2);
    return;
  }

  if (isFuncNamed(Call, C, "memzero_explicit") ||
      isFuncNamed(Call, C, "bpf_memzero")) {
    if (Call.getNumArgs() >= 2)
      recordWholeObjectZeroing(Call, C, /*DstIdx=*/0, /*SizeIdx=*/1);
