void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  unsigned LenIdx = 0;
  unsigned DataIdx = 0;
  if (!matchSink(Call, C, LenIdx, DataIdx))
    return;

  if (Call.getNumArgs() <= std::max(LenIdx, DataIdx))
    return;

  const Expr *DataExpr = Call.getArgExpr(DataIdx);
  const Expr *LenExpr = Call.getArgExpr(LenIdx);
  if (!DataExpr || !LenExpr)
    return;

  const VarDecl *VD = nullptr;
  if (!extractAddrOfLocalRecordVar(DataExpr, VD) ||
      !sizeMatchesWholeObject(LenExpr, VD, C))
    return;

  // A whole-object copy is only relevant to this checker when the object
  // layout actually contains padding bytes.
  const auto *RT = VD->getType()->getAs<RecordType>();
  if (!RT || !recordHasPadding(RT->getDecl(), C.getASTContext()))
    return;

  const MemRegion *MR = getMemRegionFromExpr(DataExpr, C);
  if (!MR)
    return;

  MR = MR->getBaseRegion();
  if (!MR || C.getState()->contains<ZeroedStructSet>(MR))
    return;

  reportLeak(Call, C);
}

