// If expression refers to a flexible-array member annotated with
// __counted_by(...), return that field.
const FieldDecl *
SAGenTestChecker::getFAMFieldIfCountedBy(const Expr *E) {
  if (!E)
    return nullptr;

  const auto *ME = dyn_cast<MemberExpr>(E->IgnoreParenImpCasts());
  if (!ME)
    return nullptr;

  const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl());
  if (!FD || !isa<IncompleteArrayType>(FD->getType().getTypePtr()))
    return nullptr;

  if (!FD->getAttr<CountedByAttr>())
    return nullptr;

  return FD;
}

// Resolve the counter field from the expression stored in CountedByAttr.
