                               unsigned &SizeArgIndex) {
  auto Match = [&](StringRef N) -> bool {
    if (const IdentifierInfo *ID = Call.getCalleeIdentifier())
      return ID->getName() == N;

    if (const Decl *D = Call.getDecl()) {
      if (const auto *FD = dyn_cast<FunctionDecl>(D)) {
        if (const IdentifierInfo *ID = FD->getIdentifier())
          return ID->getName() == N;
      }
    }
    return false;
  };

  if (Match("memcpy") || Match("__memcpy") ||
      Match("__builtin_memcpy")) {
    NameOut = "memcpy";
    SizeArgIndex = 2;
    return true;
  }

  if (Match("memmove") || Match("__memmove") ||
      Match("__builtin_memmove")) {
    NameOut = "memmove";
    SizeArgIndex = 2;
    return true;
  }

  if (Match("memset") || Match("__memset") ||
      Match("__builtin_memset")) {
    NameOut = "memset";
    SizeArgIndex = 2;
    return true;
  }

  return false;
}

// Find a field referenced by the counted_by expression.
namespace {
class CounterFieldVisitor
    : public RecursiveASTVisitor<CounterFieldVisitor> {
public:
  const FieldDecl *CounterFD = nullptr;

  bool VisitDeclRefExpr(const DeclRefExpr *DRE) {
    if (const auto *FD = dyn_cast<FieldDecl>(DRE->getDecl()))
      CounterFD = FD;
    return true;
  }

  bool VisitMemberExpr(const MemberExpr *ME) {
    if (const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl()))
      CounterFD = FD;
    return true;
  }
};
} // namespace

// If expression refers to a flexible-array member annotated with
// __counted_by(...), return that field.
const FieldDecl *
SAGenTestChecker::getFAMFieldIfCountedBy(const Expr *E) {
  if (!E)
    return nullptr;

  const auto *ME = dyn_cast<MemberExpr>(E->IgnoreParenImpCasts());
  if (!ME)
    return nullptr;

  const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl());
  if (!FD || !isa<IncompleteArrayType>(FD->getType().getTypePtr()))
    return nullptr;

  if (!FD->getAttr<CountedByAttr>())
    return nullptr;

  return FD;
}

// Resolve the counter field from the expression stored in CountedByAttr.
const FieldDecl *
SAGenTestChecker::getCounterFieldFromFAM(const FieldDecl *FAMFD) {
  if (!FAMFD)
    return nullptr;

  const auto *Attr = FAMFD->getAttr<CountedByAttr>();
  if (!Attr)
    return nullptr;

  const Expr *CountExpr = Attr->getCountExpr();
  if (!CountExpr)
    return nullptr;

  CounterFieldVisitor Visitor;
  Visitor.TraverseStmt(const_cast<Expr *>(CountExpr));
  return Visitor.CounterFD;
}

// Check whether the assigned field is the counted_by counter for a FAM in
// the same record.
bool SAGenTestChecker::isAssignmentToCounterField(
    const FieldRegion *FR, const FieldDecl *&CounterFD,
    const FieldDecl *&FAMFD) {
  if (!FR)
    return false;

  const FieldDecl *AssignedFD = FR->getDecl();
  if (!AssignedFD)
    return false;

  const RecordDecl *AssignedRecord = AssignedFD->getParent();
  if (!AssignedRecord)
    return false;

  for (const FieldDecl *Field : AssignedRecord->fields()) {
    if (!isa<IncompleteArrayType>(Field->getType().getTypePtr()))
      continue;

    const FieldDecl *CandidateCounter = getCounterFieldFromFAM(Field);
    if (!CandidateCounter)
      continue;

    if (CandidateCounter->getCanonicalDecl() ==
        AssignedFD->getCanonicalDecl()) {
      CounterFD = CandidateCounter;
      FAMFD = Field;
      return true;
    }
  }

  return false;
}

// Report function.
void SAGenTestChecker::reportEarlyFAMAccess(
    const CallEvent &Call, CheckerContext &C, const FieldDecl *FAMFD,
    const FieldDecl *CounterFD) const {
  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  llvm::SmallString<128> Msg(
      "Flexible-array accessed before initializing its __counted_by counter");
  if (FAMFD && CounterFD) {
    Msg += " ('";
    Msg += FAMFD->getName();
    Msg += "' before '";
    Msg += CounterFD->getName();
    Msg += "')";
  }

  auto R =
      std::make_unique<PathSensitiveBugReport>(*BT, StringRef(Msg), N);
  R->addRange(Call.getSourceRange());
  C.emitReport(std::move(R));
}

// Track zero-initialized allocations.
void SAGenTestChecker::checkPostCall(const CallEvent &Call,
                                     CheckerContext &C) const {
  if (!isZeroingAllocator(Call, C))
    return;

  ProgramStateRef State = C.getState();
  const MemRegion *MR = Call.getReturnValue().getAsRegion();
  if (!MR)
    return;

  const MemRegion *BaseR = MR->getBaseRegion();
  if (!BaseR)
    return;

  State = State->add<ZeroInitRegions>(BaseR);
  C.addTransition(State);
}

// Detect memcpy/memmove/memset on a __counted_by flexible-array member before
// its counter has been assigned.
void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  StringRef Name;
  unsigned SizeIdx = 0;
  if (!isMemOp(Call, C, Name, SizeIdx))
    return;

  const Expr *DestE = Call.getArgExpr(0);
  if (!DestE)
    return;

  const FieldDecl *FAMFD = getFAMFieldIfCountedBy(DestE);
  if (!FAMFD)
    return;

  const FieldDecl *CounterFD = getCounterFieldFromFAM(FAMFD);

  ProgramStateRef State = C.getState();
  SVal DstSV = Call.getArgSVal(0);
  const MemRegion *DstR = DstSV.getAsRegion();
  if (!DstR)
    return;

  const MemRegion *BaseR = getBaseForFieldOrElement(DstR);
  if (!BaseR)
    return;

  // Limit this checker to the zero-initialized allocation pattern.
  if (!State->contains<ZeroInitRegions>(BaseR))
    return;

  // A counter assignment before this access makes the ordering valid.
  if (State->contains<CounterReadyRegions>(BaseR))
    return;

  // A provably zero-sized operation does not access the flexible array.
  if (SizeIdx < Call.getNumArgs()) {
    SVal SizeSV = Call.getArgSVal(SizeIdx);
    if (std::optional<nonloc::ConcreteInt> SZ =
            SizeSV.getAs<nonloc::ConcreteInt>()) {
      if (SZ->getValue() == 0)
        return;
    }
  }

  reportEarlyFAMAccess(Call, C, FAMFD, CounterFD);
}

// Mark the object's counted_by counter as initialized when it is assigned.
// Whether the assigned value is concrete, symbolic, or zero does not affect
// the ordering property this checker tracks.
void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S,
                                CheckerContext &C) const {
  (void)Val;

  auto MRVOpt = Loc.getAs<loc::MemRegionVal>();
  if (!MRVOpt)
    return;

  const auto *FR = dyn_cast<FieldRegion>(MRVOpt->getRegion());
  if (!FR)
    return;

  const FieldDecl *CounterFD = nullptr;
  const FieldDecl *FAMFD = nullptr;
  if (!isAssignmentToCounterField(FR, CounterFD, FAMFD))
    return;

  const MemRegion *BaseR = getBaseForFieldOrElement(FR);
  if (!BaseR)
    return;

  ProgramStateRef State = C.getState();
  State = State->add<CounterReadyRegions>(BaseR);
  C.addTransition(State);
}

} // end anonymous namespace

extern "C" void clang_registerCheckers(CheckerRegistry &registry) {
  registry.addChecker<SAGenTestChecker>(
      "custom.SAGenTestChecker",
