const MemRegion *
SAGenTestChecker::getBaseForFieldOrElement(const MemRegion *R) {
  if (!R)
    return nullptr;

  const MemRegion *Cur = R;
  while (true) {
    if (const auto *ER = dyn_cast<ElementRegion>(Cur)) {
      Cur = ER->getSuperRegion();
      continue;
    }
    if (const auto *FR = dyn_cast<FieldRegion>(Cur)) {
      Cur = FR->getSuperRegion();
      continue;
    }
    break;
  }

  return Cur ? Cur->getBaseRegion() : nullptr;
}

bool SAGenTestChecker::isZeroingAllocator(const CallEvent &Call,
                                          CheckerContext &C) {
  if (const IdentifierInfo *ID = Call.getCalleeIdentifier()) {
    StringRef N = ID->getName();
    return N == "kzalloc" || N == "kvzalloc" ||
           N == "devm_kzalloc" || N == "kcalloc" ||
           N == "devm_kcalloc";
  }

  if (const Decl *D = Call.getDecl()) {
    if (const auto *FD = dyn_cast<FunctionDecl>(D)) {
      if (const IdentifierInfo *ID = FD->getIdentifier()) {
        StringRef N = ID->getName();
        return N == "kzalloc" || N == "kvzalloc" ||
               N == "devm_kzalloc" || N == "kcalloc" ||
               N == "devm_kcalloc";
      }
    }
  }

  return false;
}

bool SAGenTestChecker::isMemOp(const CallEvent &Call, CheckerContext &C,
                               StringRef &NameOut,
                               unsigned &SizeArgIndex) {
  auto Match = [&](StringRef N) -> bool {
    if (const IdentifierInfo *ID = Call.getCalleeIdentifier())
      return ID->getName() == N;
    if (const Decl *D = Call.getDecl()) {
      if (const auto *FD = dyn_cast<FunctionDecl>(D)) {
        if (const IdentifierInfo *ID = FD->getIdentifier())
          return ID->getName() == N;
      }
    }
    return false;
  };

  if (Match("memcpy") || Match("__memcpy") ||
      Match("__builtin_memcpy")) {
    NameOut = "memcpy";
    SizeArgIndex = 2;
    return true;
  }
  if (Match("memmove") || Match("__memmove") ||
      Match("__builtin_memmove")) {
    NameOut = "memmove";
    SizeArgIndex = 2;
    return true;
  }
  if (Match("memset") || Match("__memset") ||
      Match("__builtin_memset")) {
    NameOut = "memset";
    SizeArgIndex = 2;
    return true;
  }

  return false;
}

const FieldDecl *
SAGenTestChecker::getFAMFieldIfCountedBy(const Expr *E) {
  if (!E)
    return nullptr;

  const Expr *EE = E->IgnoreParenImpCasts();
  const auto *ME = dyn_cast<MemberExpr>(EE);
  if (!ME)
    return nullptr;

  const auto *FD = dyn_cast<FieldDecl>(ME->getMemberDecl());
  if (!FD || !isa<IncompleteArrayType>(FD->getType().getTypePtr()))
    return nullptr;

  if (!FD->getAttr<CountedByAttr>())
    return nullptr;

  return FD;
}

// CountedByAttr::getCount() is the count expression in Clang 18. In the
// usual counted_by(field) spelling it refers directly to the counter field.
const FieldDecl *
SAGenTestChecker::getCounterFieldFromFAM(const FieldDecl *FAMFD) {
  if (!FAMFD)
    return nullptr;

  const auto *Attr = FAMFD->getAttr<CountedByAttr>();
  if (!Attr)
    return nullptr;

  const Expr *CountExpr = Attr->getCount();
  if (!CountExpr)
    return nullptr;

  CountExpr = CountExpr->IgnoreParenImpCasts();
  if (const auto *DRE = dyn_cast<DeclRefExpr>(CountExpr))
    return dyn_cast<FieldDecl>(DRE->getDecl());
  if (const auto *ME = dyn_cast<MemberExpr>(CountExpr))
    return dyn_cast<FieldDecl>(ME->getMemberDecl());

  return nullptr;
}

bool SAGenTestChecker::isAssignmentToCounterField(
    const FieldRegion *FR, const FieldDecl *&CounterFD,
    const FieldDecl *&FAMFD) {
  if (!FR)
    return false;

  const FieldDecl *AssignedFD = FR->getDecl();
  if (!AssignedFD)
    return false;

  const RecordDecl *Parent = AssignedFD->getParent();
  if (!Parent)
    return false;

  for (const FieldDecl *Field : Parent->fields()) {
    const auto *Attr = Field->getAttr<CountedByAttr>();
    if (!Attr)
      continue;

    const FieldDecl *CountFD = getCounterFieldFromFAM(Field);
    if (!CountFD)
      continue;

    if (CountFD->getCanonicalDecl() == AssignedFD->getCanonicalDecl()) {
      CounterFD = CountFD;
      FAMFD = Field;
      return true;
    }
  }

  return false;
}

bool SAGenTestChecker::isNonZero(CheckerContext &C, SVal V,
                                 const Expr *RHSExpr) {
  if (std::optional<nonloc::ConcreteInt> CI =
          V.getAs<nonloc::ConcreteInt>()) {
    const llvm::APSInt &I = CI->getValue();
    return I.isSigned() ? I.isStrictlyPositive() : I != 0;
  }

  if (RHSExpr) {
    SVal RHSVal =
        C.getState()->getSVal(RHSExpr, C.getLocationContext());
    if (std::optional<nonloc::ConcreteInt> CI =
            RHSVal.getAs<nonloc::ConcreteInt>()) {
      const llvm::APSInt &I = CI->getValue();
      return I.isSigned() ? I.isStrictlyPositive() : I != 0;
    }
  }

  return false;
}

void SAGenTestChecker::reportEarlyFAMAccess(
    const CallEvent &Call, CheckerContext &C, const FieldDecl *FAMFD,
    const FieldDecl *CounterFD) const {
  ExplodedNode *N = C.generateNonFatalErrorNode();
  if (!N)
    return;

  llvm::SmallString<128> Msg(
      "Flexible-array accessed before initializing its __counted_by counter");
  if (FAMFD && CounterFD) {
    Msg += " ('";
    Msg += FAMFD->getName();
    Msg += "' before '";
    Msg += CounterFD->getName();
    Msg += "')";
  }

  auto R = std::make_unique<PathSensitiveBugReport>(*BT, StringRef(Msg), N);
  R->addRange(Call.getSourceRange());
  C.emitReport(std::move(R));
}

void SAGenTestChecker::checkPostCall(const CallEvent &Call,
                                     CheckerContext &C) const {
  if (!isZeroingAllocator(Call, C))
    return;

  ProgramStateRef State = C.getState();
  const MemRegion *MR = Call.getReturnValue().getAsRegion();
  if (!MR)
    return;

  const MemRegion *BaseR = MR->getBaseRegion();
  if (!BaseR)
    return;

  State = State->add<ZeroInitRegions>(BaseR);
  C.addTransition(State);
}

void SAGenTestChecker::checkPreCall(const CallEvent &Call,
                                    CheckerContext &C) const {
  StringRef Name;
  unsigned SizeIdx = 0;
  if (!isMemOp(Call, C, Name, SizeIdx))
    return;

  const Expr *DestE = Call.getArgExpr(0);
  if (!DestE)
    return;

  const FieldDecl *FAMFD = getFAMFieldIfCountedBy(DestE);
  if (!FAMFD)
    return;

  const FieldDecl *CounterFD = getCounterFieldFromFAM(FAMFD);

  ProgramStateRef State = C.getState();
  SVal DstSV = Call.getArgSVal(0);
  const MemRegion *DstR = DstSV.getAsRegion();
  if (!DstR)
    return;

  const MemRegion *BaseR = getBaseForFieldOrElement(DstR);
  if (!BaseR || !State->contains<ZeroInitRegions>(BaseR))
    return;

  // An assignment of an unknown symbolic value still initializes the
  // counted_by field. Explicit zero assignments remain unready.
  if (State->contains<CounterReadyRegions>(BaseR))
    return;

  if (SizeIdx < Call.getNumArgs()) {
    if (std::optional<nonloc::ConcreteInt> SZ =
            Call.getArgSVal(SizeIdx).getAs<nonloc::ConcreteInt>()) {
      if (SZ->getValue() == 0)
        return;
    }
  }

  reportEarlyFAMAccess(Call, C, FAMFD, CounterFD);
}

void SAGenTestChecker::checkBind(SVal Loc, SVal Val, const Stmt *S,
                                 CheckerContext &C) const {
  auto MRVOpt = Loc.getAs<loc::MemRegionVal>();
  if (!MRVOpt)
    return;

  const auto *FR = dyn_cast<FieldRegion>(MRVOpt->getRegion());
  if (!FR)
    return;

  const FieldDecl *CounterFD = nullptr;
  const FieldDecl *FAMFD = nullptr;
  if (!isAssignmentToCounterField(FR, CounterFD, FAMFD))
    return;

  const MemRegion *BaseR = getBaseForFieldOrElement(FR);
  if (!BaseR)
    return;

  const Expr *RHSExpr = nullptr;
  if (const auto *BO = dyn_cast_or_null<BinaryOperator>(S)) {
    if (BO->isAssignmentOp())
      RHSExpr = BO->getRHS();
  }

  ProgramStateRef State = C.getState();
  bool IsZero = false;
  if (std::optional<nonloc::ConcreteInt> CI =
          Val.getAs<nonloc::ConcreteInt>()) {
    IsZero = CI->getValue() == 0;
  } else if (RHSExpr) {
    SVal RHSVal = State->getSVal(RHSExpr, C.getLocationContext());
    if (std::optional<nonloc::ConcreteInt> CI =
            RHSVal.getAs<nonloc::ConcreteInt>())
      IsZero = CI->getValue() == 0;
  }

  // A known zero counter cannot provide bounds for a nonzero access.
  // Symbolic values are treated as initialized, avoiding warnings for
  // assignments such as event->datalen = datalen.
  if (IsZero)
    State = State->remove<CounterReadyRegions>(BaseR);
  else
    State = State->add<CounterReadyRegions>(BaseR);

  C.addTransition(State);
}

