// usual counted_by(field) spelling it refers directly to the counter field.
const FieldDecl *
SAGenTestChecker::getCounterFieldFromFAM(const FieldDecl *FAMFD) {
  if (!FAMFD)
    return nullptr;

  const auto *Attr = FAMFD->getAttr<CountedByAttr>();
  if (!Attr)
    return nullptr;

  const Expr *CountExpr = Attr->getCount();
  if (!CountExpr)
    return nullptr;

  CountExpr = CountExpr->IgnoreParenImpCasts();
  if (const auto *DRE = dyn_cast<DeclRefExpr>(CountExpr))
    return dyn_cast<FieldDecl>(DRE->getDecl());
  if (const auto *ME = dyn_cast<MemberExpr>(CountExpr))
    return dyn_cast<FieldDecl>(ME->getMemberDecl());

  return nullptr;
}

bool SAGenTestChecker::isAssignmentToCounterField(
    const FieldRegion *FR, const FieldDecl *&CounterFD,
    const FieldDecl *&FAMFD) {
  if (!FR)
    return false;

  const FieldDecl *AssignedFD = FR->getDecl();
  if (!AssignedFD)
    return false;

  const RecordDecl *Parent = AssignedFD->getParent();
  if (!Parent)
    return false;

  for (const FieldDecl *Field : Parent->fields()) {
    const auto *Attr = Field->getAttr<CountedByAttr>();
    if (!Attr)
      continue;

    const FieldDecl *CountFD = getCounterFieldFromFAM(Field);
    if (!CountFD)
      continue;

    if (CountFD->getCanonicalDecl() == AssignedFD->getCanonicalDecl()) {
      CounterFD = CountFD;
      FAMFD = Field;
      return true;
    }
  }

  return false;
}

